package com.ias.ticket;
import com.ias.trust.*;
import jakarta.servlet.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import java.util.*;

@RestController
public class SupplementFiles {
 final Tickets t;final FileStore files;final Supplements supplements;
 public SupplementFiles(Tickets t,FileStore files,Supplements supplements){this.t=t;this.files=files;this.supplements=supplements;}
 @PostMapping("/api/ticket/tickets/{key}/supplement-requests/{request}/files") ResponseEntity<?> upload(@PathVariable String key,@PathVariable String request,HttpServletRequest r)throws Exception{Tickets.uuid(key);Tickets.uuid(request);r.setAttribute("ias.supplement.ticket",key);r.setAttribute("ias.supplement.request",request);return files.upload(r);}
 static String ticket(HttpServletRequest r){return (String)r.getAttribute("ias.supplement.ticket");}
 static String request(HttpServletRequest r){return (String)r.getAttribute("ias.supplement.request");}
 static boolean isSupplement(Map<String,Object>f){return f.get("supplement_request_id")!=null;}
 static Map<String,Object> dto(Map<String,Object>f){var out=FileStore.dto(f);out.remove("submissionId");out.put("ticketId",f.get("supplement_ticket_id"));out.put("roundId",f.get("supplement_round_id"));out.put("requestId",f.get("supplement_request_id"));out.put("replyOperationId",f.get("reply_operation_id"));return out;}
 void context(Map<String,Object>f,String key,String request,String reply){if(!Objects.equals(f.get("supplement_ticket_id"),key)||!Objects.equals(f.get("supplement_request_id"),request)||reply!=null&&!Objects.equals(f.get("reply_operation_id"),reply))throw new Problem(404,"TARGET_NOT_ACCESSIBLE");}
 Map<String,Object> register(Tickets.Actor a,String key,String request,String reply,String upload,String sha,String name,String generation){
  return t.tx.execute(tx->{t.lockActor(a.tenant(),a.user());t.db.queryForMap("SELECT id FROM ticket_record WHERE id=? AND tenant_id=? FOR UPDATE",key,a.tenant());var req=supplements.customer(key,request,a,true);var rows=t.db.queryForList("SELECT * FROM ticket_file WHERE upload_id=? FOR UPDATE",upload);
   if(!rows.isEmpty()){var old=rows.getFirst();if(Tickets.id(old.get("tenant_id"))!=a.tenant()||Tickets.id(old.get("user_id"))!=a.user())throw new Problem(404,"TARGET_NOT_ACCESSIBLE");if(!Objects.equals(old.get("supplement_ticket_id"),key)||!Objects.equals(old.get("supplement_request_id"),request)||!Objects.equals(old.get("reply_operation_id"),reply)||!old.get("sha256").equals(sha)||!old.get("name").equals(name))throw new Problem(409,"IDEMPOTENCY_CONFLICT");if(old.get("state").equals("READY"))return old;if(!old.get("state").equals("FAILED"))throw new Problem(409,"OPERATION_BUSY");t.db.update("UPDATE ticket_file SET state='UPLOADING',generation=?,lease_until=TIMESTAMPADD(SECOND,120,UTC_TIMESTAMP(3)),updated_at=UTC_TIMESTAMP(3) WHERE id=?",generation,old.get("id"));return t.db.queryForMap("SELECT * FROM ticket_file WHERE id=?",old.get("id"));}
   if(!t.db.queryForList("SELECT operation_id FROM ticket_action_operation WHERE operation_id=?",reply).isEmpty())throw new Problem(409,"IDEMPOTENCY_CONFLICT");if(t.db.queryForObject("SELECT COUNT(*) FROM ticket_file WHERE tenant_id=? AND user_id=? AND supplement_request_id=? AND reply_operation_id=? AND state NOT IN ('DELETING','DELETED')",Long.class,a.tenant(),a.user(),request,reply)>=5)throw new Problem(409,"FILE_LIMIT");String id=UUID.randomUUID().toString();
   // Supplemental files have no report submission context.
   t.db.update("INSERT INTO ticket_file(id,upload_id,submission_id,tenant_id,user_id,device_id,ownership_version,name,sha256,state,generation,lease_until,created_at,updated_at,supplement_ticket_id,supplement_round_id,supplement_request_id,reply_operation_id) VALUES(?,?,NULL,?,?,NULL,NULL,?,?,'UPLOADING',?,TIMESTAMPADD(SECOND,120,UTC_TIMESTAMP(3)),UTC_TIMESTAMP(3),UTC_TIMESTAMP(3),?,?,?,?)",id,upload,a.tenant(),a.user(),name,sha,generation,key,req.get("round_id"),request,reply);return t.db.queryForMap("SELECT * FROM ticket_file WHERE id=?",id);
  });
 }
 void lockContext(Tickets.Actor a,String key,String request){t.db.queryForMap("SELECT id FROM ticket_record WHERE id=? AND tenant_id=? FOR UPDATE",key,a.tenant());supplements.customer(key,request,a,true);}
 @GetMapping("/api/ticket/tickets/{key}/supplement-requests/{request}/file-uploads/{upload}") Map<String,Object> lookup(@PathVariable String key,@PathVariable String request,@PathVariable String upload,HttpServletRequest r){var a=t.actor(r,false);t.accessible(Tickets.uuid(key),a);Tickets.uuid(request);var f=files.own(upload,a,true);context(f,key,request,null);return dto(f);}
 @DeleteMapping("/api/ticket/tickets/{key}/supplement-requests/{request}/files/{id}") Map<String,Object> delete(@PathVariable String key,@PathVariable String request,@PathVariable String id,HttpServletRequest r){if(r.getParameterMap().size()!=1||r.getParameterValues("replyOperationId")==null||r.getParameterValues("replyOperationId").length!=1)throw Tickets.bad();String reply=Tickets.uuid(r.getParameter("replyOperationId"));Tickets.uuid(key);Tickets.uuid(request);var a=supplements.actor(r,true);var f=files.own(id,a,false);context(f,key,request,reply);t.tx.executeWithoutResult(tx->{t.lockActor(a.tenant(),a.user());lockContext(a,key,request);var locked=t.db.queryForMap("SELECT * FROM ticket_file WHERE id=? FOR UPDATE",id);if(t.db.queryForObject("SELECT COUNT(*) FROM ticket_file_reference WHERE file_id=?",Long.class,id)>0)throw new Problem(409,"FILE_REFERENCED");if(locked.get("state").equals("UPLOADING"))throw new Problem(409,"OPERATION_BUSY");if(!locked.get("state").equals("DELETED"))t.db.update("UPDATE ticket_file SET state='DELETING',generation=NULL,lease_until=NULL,updated_at=UTC_TIMESTAMP(3) WHERE id=?",id);});files.remove(id);return Map.of("fileId",id,"state",t.db.queryForObject("SELECT state FROM ticket_file WHERE id=?",String.class,id));}
}
